-- public.building_floor_near(p_world uuid, p_building integer, p_x integer, p_y integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.building_floor_near(p_world uuid, p_building integer, p_x integer, p_y integer)
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce((select f.top from foundation f where f.world_id = p_world and f.x = p_x + d.dx and f.y = p_y + d.dy
                     and bill_done(f.needed)),
                  land_height(p_world, p_x + d.dx, p_y + d.dy))
  from (values (1, 0, 0), (-1, 0, 1), (0, 1, 2), (0, -1, 3)) d(dx, dy, ord)
  where building_at(p_world, p_x + d.dx, p_y + d.dy) = p_building
  order by d.ord limit 1
$function$
